      "title": "Собрать документы и подготовить перевод на португальский",
      "text": "Проверьте паспорт, подтверждения рождения и родства, справки о несудимости и доказательства основания по своей карточке услуги. Универсального комплекта на все случаи нет.\n\nPolícia Federal указывает апостиль или легализацию и присяжный перевод на португальский в Бразилии, с применимыми договорными исключениями. Уточните исключение для своего документа, прежде чем оплачивать оформление.\n\nАпостиль оформляет компетентное ведомство: ЗАГС, МВД либо Минюст в зависимости от документа. На странице услуги Минюста указана пошлина 2 500 ₽ за документ. Это не сбор за бразильскую резиденцию.",
