      "text": "Соглашение предусматривает до 90 дней за каждый период 180 дней при соблюдении условий въезда. Туристическое пребывание не означает право на работу или резиденцию.\n\nДля граждан вне MERCOSUR доступны предусмотренные законом основания: работа, учёба, rentista, pensionado, семейная связь и другие. Внутри страны применяется соответствующая процедура Migraciones/RaDEX; из-за рубежа — консульская процедура либо разрешение на въезд.",
