      "text": "По рабочему маршруту нужны документы, удостоверяющие личность, подтверждения адреса и законного въезда, а также документы работодателя. Для лиц старше 16 лет карточка услуги предусматривает иностранные справки о несудимости из стран проживания более года за последние три года. Для других оснований проверяйте свой список.\n\nИностранные документы требуют апостиля или легализации; документы на других языках переводятся на испанский аргентинским публичным переводчиком с удостоверением соответствующей коллегией. Проверьте оригиналы и допустимые копии.\n\nВыберите ведомство для оформления апостиля в зависимости от документа: ЗАГС, МВД или Минюст — в пределах его компетенции. Пошлина Минюста в размере 2 500 ₽ за документ относится к российской услуге, а не к подаче заявления в Аргентине.",
