    "description": "Шанхай, городские набережные и архитектура большого масштаба.",
    "safety": "Тяжкие преступления против иностранцев относительно редки, но бывают кражи и мошенничество. Важны также местные законы и риск ограничений выезда при спорах.",
    "currency": "CNY",
