      "text": "С 15 сентября 2026 года общая схема на 60 дней отменена. По сообщению посольства, владельцы обычных паспортов РФ сохраняют безвизовый въезд до 30 дней по двустороннему соглашению. Проверяйте разрешённую дату выезда по отметке при въезде.\n\nПодберите отдельное основание: DTV для подходящего сценария, Non-Immigrant B для работы, ED для обучения или O для применимых семейных обстоятельств. Туристический въезд сам по себе не даёт права работать в Таиланде. Для местной работы согласуйте с работодателем визу и разрешение на работу.",
