      "text": "Запросите актуальный перечень BI, учебного заведения или работодателя: паспорт, документы о родстве, образовании и другие подтверждения требуются в зависимости от основания. Не заказывайте справки заранее без проверки срока их действия.\n\nПосольство Филиппин в Москве подтверждает применение апостиля к российским публичным документам вместо консульской легализации. Апостиль ставит компетентное ведомство страны выдачи. Требования к переводу на английский язык согласуйте с принимающей организацией; апостиль не заменяет перевод.",
