      "title": "Согласовать ввоз питомца до покупки билетов",
      "text": "Россия входит в список CDC стран высокого риска бешенства собак. Для собаки с зарубежной вакцинацией, находившейся там в последние шесть месяцев, действуют дополнительные требования: возраст от шести месяцев, микрочип до вакцинации, ветеринарная форма с государственным заверением и квитанция CDC Dog Import Form.\n\nНужны бронирование зарегистрированного CDC центра и прилёт в аэропорт, где он расположен. При отсутствии допустимого анализа титра бронирование включает 28-дневный карантин. Условия лаборатории, сроки и расходы согласуйте до бронирования поездки.\n\nAPHIS не устанавливает собственных ветеринарных требований для ввоза домашней кошки, но остаются требования других ведомств, штата и авиакомпании. Вес, порода, переноска и транзит влияют на возможность перевозки и цену.",
