      "text": "Подготовьте паспорт, документы об образовании и опыте, а при необходимости — свидетельства о рождении, браке и разводе, справки о несудимости. Перечень зависит от петиции и консульского процесса.\n\nВ таблице Госдепартамента для РФ указаны допустимые документы и органы выдачи. Не заказывайте апостиль на весь комплект автоматически: уточните требование получателя для каждого документа.\n\nСледуйте инструкции конкретного ведомства и консульства. Для загрузки в CEAC Госдепартамент рекомендует объединять исходный документ и его заверенный перевод в один файл. Сохраните оригиналы для интервью.",
