      "title": "Проверить право на работу и доход",
      "text": "Для международной удалённой работы есть отдельный маршрут UGE. Проверьте документы о зарубежном работодателе или клиентах, квалификации либо опыте, доходе и социальном страховании. Условия для сотрудника и самостоятельного специалиста различаются; семейные члены увеличивают требуемые средства.",
