      "text": "Бали — остров и провинция Индонезии, поэтому въезд регулируется индонезийскими правилами. Россия включена в опубликованный список Visa on Arrival. B1 предусматривает первоначально до 30 дней и одно продление до 60 дней общего пребывания; опубликованный сбор —500 000 IDR. Перед оплатой повторно выберите Russia на официальном e-Visa и проверьте доступность категории, паспорт и обратный билет. Туристическая виза не даёт права на местную работу.",
